def is_right_angled(x, y, z):
    a, b, c = sorted((x, y, z))           # the longest side must be c
    return a * a + b * b == c * c

for sides in [(3, 4, 5), (5, 12, 13), (6, 7, 9), (20, 21, 29), (7, 8, 11)]:
    print(sides, "right angle" if is_right_angled(*sides) else "not a right angle")

from math import gcd

# Euclid's formula: for m > n > 0, coprime and not both odd,
# a = m^2 - n^2, b = 2mn, c = m^2 + n^2 is a primitive Pythagorean triple
triples = []
for m in range(2, 8):
    for n in range(1, m):
        if gcd(m, n) == 1 and (m - n) % 2 == 1:
            a, b, c = m*m - n*n, 2*m*n, m*m + n*n
            if c <= 50:
                triples.append(tuple(sorted((a, b)) + [c]))

for a, b, c in sorted(triples, key=lambda t: t[2]):
    assert a*a + b*b == c*c
    print(f"{a:>2}, {b:>2}, {c:>2}    {a*a:>4} + {b*b:>4} = {c*c:>4}")
print(len(triples), "primitive triples with a hypotenuse of 50 or less")
